/* Loads the assets generated by tools/extract_assets.py. */
import { MovieClip, TextField } from "./flash.js";

export class AssetLibrary {
  constructor() {
    this.data = null;
    this.sprites = {};
    this.shapes = {};
    this.textures = [];     // ImageBitmap per atlas page
    this.pages = [];
    this.fonts = {};
    this.sounds = {};
    this.levels = [];
    this.flavours = null;
    this.textFields = {};
    this.loaded = false;
  }

  async load(onProgress) {
    const data = await (await fetch("assets/assets.json")).json();
    this.data = data;
    this.sprites = data.sprites;
    this.shapes = data.shapes;
    this.pages = data.pages;
    this.fonts = data.fonts;
    this.flavours = data.flavours;
    this.textFields = data.textFields;
    let done = 0;
    const total = data.pages.length + Object.keys(data.fonts).length + 1 + Object.keys(data.sounds).length;
    const tick = () => { done++; onProgress && onProgress(done / total); };

    // Fonts: register each embedded TTF with the document so canvas can use it.
    const fontLoads = [];
    for (const [id, f] of Object.entries(data.fonts)) {
      const name = f.name;
      try {
        const face = new FontFace(name, `url("${encodeURI("assets/" + f.file)}")`);
        document.fonts.add(face);
        fontLoads.push(face.load().then(() => { tick(); }).catch(() => { tick(); }));
      } catch (e) { tick(); }
    }
    await Promise.all(fontLoads);

    // Atlas pages
    for (const p of data.pages) {
      const img = await fetch("assets/" + p).then(r => r.blob()).then(b => createImageBitmap(b));
      this.textures.push(img);
      tick();
    }

    // Sounds
    const { AudioSystem } = await import("./flash.js");
    await AudioSystem.init();
    const soundLoads = [];
    for (const [id, file] of Object.entries(data.sounds)) {
      soundLoads.push(AudioSystem.load(Number(id), "assets/" + file).then(() => tick()).catch(() => tick()));
    }
    await Promise.all(soundLoads);

    // Levels and attract-mode replays
    this.levels = await (await fetch("assets/data/levels.json")).json();
    try { this.attract = await (await fetch("assets/data/attract.json")).json(); }
    catch (e) { this.attract = []; }
    tick();
    this.loaded = true;
    globalThis.AssetLibrary = this;
  }

  levelSet(ep) {
    const out = [];
    for (const l of this.levels) if (l.e === ep) out.push(l);
    out.sort((a, b) => a.i - b.i);
    return out.map(l => ({ name: l.name, data: l.data }));
  }

  makeTextField(spec = {}) {
    const t = new TextField();
    t._font = spec.font || "uni 05_53_8pt_st";
    t._fontSize = spec.size || 8;
    t.textColor = spec.color != null ? spec.color : 0x000000;
    t._align = spec.align || "left";
    t._textW = spec.w || 20;
    t._textH = spec.h || 10;
    t._bounds = [0, 0, t._textW, t._textH];
    if (spec.text != null) { t.text = spec.text; }
    return t;
  }
}

/** Create a MovieClip asset class (the AS3 side used `new asset_gfx_foo()`). */
export function clip(name) {
  return class extends MovieClip {
    constructor() { super(name); }
  };
}

